block.template:
{# Beispiel 7 · Termin-Hinweis: Datumsfeld mit date('…') und maschinenlesbarem <time>. #}
<div class="event">
  {% if datum %}
  <p class="event__sheet" aria-hidden="true"><span class="event__dow">{{ datum | date('weekday') }}</span><span class="event__day">{{ datum | date('day_month') }}</span></p>
  {% endif %}
  <div class="event__body">
    <h2 class="event__title" id="{{ block.title_id }}">{{ title }}</h2>
    <ul class="event__meta" role="list">
      {% if datum %}<li><span class="event__ico" aria-hidden="true">{{ 'calendar-blank' | icon }}</span><time datetime="{{ datum }}">{{ datum | date('long') }}</time></li>{% endif %}
      {% if uhrzeit %}<li><span class="event__ico" aria-hidden="true">{{ 'clock' | icon }}</span>{{ uhrzeit }}</li>{% endif %}
      {% if ort %}<li><span class="event__ico" aria-hidden="true">{{ 'map-pin' | icon }}</span>{{ ort }}</li>{% endif %}
    </ul>
    {% if text %}<p class="event__text">{{ text }}</p>{% endif %}
    {% if link %}<p class="event__cta"><a class="event__btn" href="{{ link }}">{{ linktext | default('Mehr erfahren') }}</a></p>{% endif %}
  </div>
</div>

block.css:
.event {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 1.25rem 2rem;
  padding: clamp(1.25rem, 3vw, 2rem);
  border: 1px solid var(--cb-line);
  border-radius: var(--cb-radius);
  background: var(--cb-surface);
}
.event__sheet {
  display: flex;
  flex: none;
  flex-direction: column;
  align-items: center;
  min-width: 8.5rem;
  margin: 0;
  padding: 1rem 1.25rem;
  border-radius: var(--cb-radius);
  background: var(--cb-accent);
  color: var(--cb-on-accent);
  text-align: center;
}
.event__dow { font-size: .8rem; letter-spacing: .06em; text-transform: uppercase; }
.event__day { font-size: 1.5rem; font-weight: 700; line-height: 1.15; }
.event__body { flex: 1 1 18rem; min-width: 0; }
.event__title { margin: 0 0 .6rem; }
.event__meta { display: flex; flex-wrap: wrap; gap: .4rem 1.25rem; margin: 0 0 .9rem; padding: 0; list-style: none; }
.event__meta li { display: inline-flex; align-items: center; gap: .4rem; }
.event__ico { display: inline-flex; font-size: 1.1rem; }
.event__text { max-width: 42rem; margin: 0 0 1rem; }
.event__cta { margin: 0; }
.event__btn {
  display: inline-block;
  padding: .7rem 1.25rem;
  border-radius: var(--cb-radius);
  background: var(--cb-accent);
  color: var(--cb-on-accent);
  font-weight: 600;
  text-decoration: none;
}
.event__btn:hover { text-decoration: underline; }
.event__btn:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
